import math
from itertools import product

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def gcd3(a, b, c):
    return gcd(a, gcd(b, c))

def is_good_set(a, b, c):
    # Assume a < b < c
    if gcd3(a, b, c) != 1:
        return False

    # C2: c | ab
    if (a * b) % c != 0:
        return False

    # C3: b | ac
    if (a * c) % b != 0:
        return False

    # C4: a | bc
    if (b * c) % a != 0:
        return False

    return True

good_numbers = set()
limit = 100 # Starting limit for c

# Iterate to find good sets {a, b, c} where a < b < c
a = 2
while True:
    b = a + 1
    while True:
        c = b + 1
        while c <= limit:
            if is_good_set(a, b, c):
                m = a * b * c
                good_numbers.add(m)
            c += 1
        b += 1
    a += 1

# Sort and print the first 20
sorted_numbers = sorted(list(good_numbers))
print(sorted_numbers[:20])

# If less than 20 are found, increase limit and search more aggressively
if len(sorted_numbers) < 20:
    print(f"Found {len(sorted_numbers)} numbers. Increasing limit to 200...")
    limit = 200
    good_numbers.clear()

    a = 2
    while True:
        b = a + 1
        while True:
            c = b + 1
            while c <= limit:
                if is_good_set(a, b, c):
                    m = a * b * c
                    good_numbers.add(m)
                c += 1
            b += 1
        a += 1

    sorted_numbers = sorted(list(good_numbers))
    print(sorted_numbers[:20])
else:
    print("Found 20 or more numbers with limit 100.")

