target_count = 20

while len(found_good_numbers) < target_count:
    M += 1

    # Optimization: Only check M if it's large enough (M >= 2*3*4 = 24)
    if M < 24:
        continue

    # Find all distinct factor triplets (a, b, c) such that abc = M and a < b < c
    # This uses a recursive approach for finding partitions into three distinct factors.

